/* vtable layout signature: 7a2509afb0544054 (shared methods: 213) */
__attribute__((weak)) void jeti_verify_vtable_sig(unsigned long long winner, unsigned long long mine, const char *method_list) {
    if (winner != mine) {
        fprintf(stderr,
            "jeti: fatal: vtable layout mismatch across translation units.\n"
            "  linked vtable sig %016llx, this translation unit sig %016llx\n"
            "\n"
            "Jeti builds one uniform 'struct jeti_vtable' per translation unit over the\n"
            "public method segment: the selectors declared in the @interfaces the TUs\n"
            "import (or the shared --slots manifest). R1 keeps that segment at\n"
            "identical slot indices in every TU, so two TUs whose public segments\n"
            "disagree dispatch through different layouts, while the linker\n"
            "weak-merges the vtable instances into one allocation.\n"
            "\n"
            "Re-running jetic does NOT help: the shared method sets really do differ.\n"
            "The usual cause is the two TUs importing different or differently\n"
            "versioned headers. Make the shared declarations identical, or build the\n"
            "affected classes as a single TU. TU-local private methods do not\n"
            "participate in this check.\n"
            "See tests/multi_tu/ for worked examples of what does and does not link.\n"
            "\nMethods known to this TU:\n  %s\n",
            (unsigned long long)winner, (unsigned long long)mine, method_list);
        abort();
    }
}

__attribute__((weak)) void jeti_verify_layout_sig(unsigned long long winner, unsigned long long mine, const char *winner_text, const char *mine_text) {
    if (winner != mine) {
        fprintf(stderr,
            "jeti: fatal: class ivar layout mismatch across translation units.\n"
            "  linked layout sig %016llx, this translation unit sig %016llx\n"
            "\n"
            "Every class struct inlines its ancestors' ivars in declaration order, so\n"
            "two TUs that saw different ivar sections write and read different\n"
            "offsets for the same field — silently, as garbage values. The usual\n"
            "cause is a stale `.hje`: one TU was compiled against an older copy of\n"
            "the header that declares this class (an ivar was added, removed or\n"
            "retyped after that TU was linked in).\n"
            "\n"
            "  linked side : %s\n"
            "  this TU     : %s\n",
            (unsigned long long)winner, (unsigned long long)mine,
            winner_text ? winner_text : "?", mine_text ? mine_text : "?");
        abort();
    }
}

